const fs = require('node:fs');
const path = require('node:path');
const { Given, When, Then } = require('@cucumber/cucumber');

const ROOT = path.resolve(__dirname, '..', '..');

function filePath(p) {
  return path.resolve(ROOT, p);
}

// ── entry-point steps ──

Given('a file exists at {string}', function (p) {
  if (!fs.existsSync(filePath(p)))
    throw new Error(`Expected ${p} to exist`);
});

Then('the file {string} contains the text {string}', function (p, text) {
  const content = fs.readFileSync(filePath(p), 'utf8');
  if (!content.includes(text))
    throw new Error(`Expected ${p} to contain "${text}"`);
});

// ── todo-app steps ──

Given('the app is loaded with no persisted todos', function () {
  this.localStorage.clear();
});

When('the user adds a todo {string}', function (title) {
  const input = this.document.querySelector('.new-todo');
  input.value = title;
  input.dispatchEvent(new this.window.Event('input', { bubbles: true }));
  input.dispatchEvent(new this.window.KeyboardEvent('keydown', { key: 'Enter', keyCode: 13, bubbles: true }));
});

When('the user types {string} and presses Enter', function (text) {
  const input = this.document.querySelector('.new-todo');
  input.value = text;
  input.dispatchEvent(new this.window.Event('input', { bubbles: true }));
  input.dispatchEvent(new this.window.KeyboardEvent('keydown', { key: 'Enter', keyCode: 13, bubbles: true }));
});

When('the user toggles the todo at position {int}', function (pos) {
  const toggles = this.document.querySelectorAll('.todo-list .toggle');
  toggles[pos - 1].click();
});

When('the user destroys the todo at position {int}', function (pos) {
  const items = this.document.querySelectorAll('.todo-list li');
  const li = items[pos - 1];
  li.querySelector('.destroy').click();
});

When('the user toggles mark-all-as-complete', function () {
  this.document.querySelector('#toggle-all').click();
});

When('the user clicks clear-completed', function () {
  this.document.querySelector('.clear-completed').click();
});

When('the user double-clicks the todo at position {int}', function (pos) {
  const labels = this.document.querySelectorAll('.todo-list .view label');
  const label = labels[pos - 1];
  const event = new this.window.MouseEvent('dblclick', { bubbles: true });
  label.dispatchEvent(event);
});

When('the edit input at position {int} is changed to {string}', function (pos, text) {
  const edits = this.document.querySelectorAll('.todo-list .edit');
  const input = edits[pos - 1];
  input.value = text;
  input.dispatchEvent(new this.window.Event('input', { bubbles: true }));
});

When('the edit input at position {int} receives Enter', function (pos) {
  const edits = this.document.querySelectorAll('.todo-list .edit');
  const input = edits[pos - 1];
  input.dispatchEvent(new this.window.KeyboardEvent('keydown', { key: 'Enter', keyCode: 13, bubbles: true }));
});

When('the edit input at position {int} receives blur', function (pos) {
  const edits = this.document.querySelectorAll('.todo-list .edit');
  const input = edits[pos - 1];
  input.dispatchEvent(new this.window.Event('blur', { bubbles: true }));
});

When('the edit input at position {int} receives Escape', function (pos) {
  const edits = this.document.querySelectorAll('.todo-list .edit');
  const input = edits[pos - 1];
  input.dispatchEvent(new this.window.KeyboardEvent('keydown', { key: 'Escape', keyCode: 27, bubbles: true }));
});

When('the user navigates to {string}', function (hash) {
  this.navigate(hash);
});

When('the app is reloaded', function () {
  const todos = this.localStorage.getItem('todos-todomvc');
  this.disposeApp();
  this.loadApp();
  if (todos) this.localStorage.setItem('todos-todomvc', todos);
  // Re-fire lifecycle events after re-adding persisted state
});

Then('the main section is not visible', function () {
  const main = this.document.querySelector('.main');
  if (main.style.display !== 'none' && !main.hidden)
    throw new Error('Expected main section to be hidden');
});

Then('the footer is not visible', function () {
  const footer = this.document.querySelector('.footer');
  if (footer.style.display !== 'none' && !footer.hidden)
    throw new Error('Expected footer to be hidden');
});

Then('the main section is visible', function () {
  const main = this.document.querySelector('.main');
  if (main.style.display === 'none' || main.hidden)
    throw new Error('Expected main section to be visible');
});

Then('the footer is visible', function () {
  const footer = this.document.querySelector('.footer');
  if (footer.style.display === 'none' || footer.hidden)
    throw new Error('Expected footer to be visible');
});

Then('the todo list contains {int} item(s)', function (count) {
  const items = this.document.querySelectorAll('.todo-list li');
  if (items.length !== count)
    throw new Error(`Expected ${count} items, got ${items.length}`);
});

Then('the todo at position {int} has text {string} and is not completed', function (pos, text) {
  const items = this.document.querySelectorAll('.todo-list li');
  const li = items[pos - 1];
  if (!li) throw new Error(`No todo at position ${pos}`);
  const label = li.querySelector('.view label');
  if (label.textContent !== text)
    throw new Error(`Expected text "${text}", got "${label.textContent}"`);
  if (li.classList.contains('completed'))
    throw new Error(`Expected todo not to be completed`);
});

Then('the todo at position {int} has text {string} and is completed', function (pos, text) {
  const items = this.document.querySelectorAll('.todo-list li');
  const li = items[pos - 1];
  if (!li) throw new Error(`No todo at position ${pos}`);
  const label = li.querySelector('.view label');
  if (label.textContent !== text)
    throw new Error(`Expected text "${text}", got "${label.textContent}"`);
  if (!li.classList.contains('completed'))
    throw new Error(`Expected todo to be completed`);
});

Then('the new-todo input is empty', function () {
  const input = this.document.querySelector('.new-todo');
  if (input.value !== '')
    throw new Error(`Expected input to be empty, got "${input.value}"`);
});

Then('the new-todo input is focused', function () {
  const input = this.document.querySelector('.new-todo');
  if (this.document.activeElement !== input)
    throw new Error('Expected new-todo input to be focused');
});

Then('the mark-all-as-complete checkbox is checked', function () {
  const toggle = this.document.querySelector('#toggle-all');
  if (!toggle.checked)
    throw new Error('Expected toggle-all to be checked');
});

Then('the mark-all-as-complete checkbox is not checked', function () {
  const toggle = this.document.querySelector('#toggle-all');
  if (toggle.checked)
    throw new Error('Expected toggle-all to be unchecked');
});

Then('the counter text is {string}', function (text) {
  const counter = this.document.querySelector('.todo-count');
  if (counter.textContent.trim() !== text)
    throw new Error(`Expected counter "${text}", got "${counter.textContent.trim()}"`);
});

Then('the clear-completed button is not visible', function () {
  const btn = this.document.querySelector('.clear-completed');
  if (btn.style.display !== 'none' && !btn.hidden)
    throw new Error('Expected clear-completed to be hidden');
});

Then('the clear-completed button is visible', function () {
  const btn = this.document.querySelector('.clear-completed');
  if (btn.style.display === 'none' || btn.hidden)
    throw new Error('Expected clear-completed to be visible');
});

Then('the todo at position {int} is in editing mode', function (pos) {
  const items = this.document.querySelectorAll('.todo-list li');
  const li = items[pos - 1];
  if (!li.classList.contains('editing'))
    throw new Error(`Expected todo at position ${pos} to be in editing mode`);
});

Then('the todo at position {int} is not in editing mode', function (pos) {
  const items = this.document.querySelectorAll('.todo-list li');
  const li = items[pos - 1];
  if (li.classList.contains('editing'))
    throw new Error(`Expected todo at position ${pos} not to be in editing mode`);
});

Then('the edit input at position {int} has value {string}', function (pos, text) {
  const edits = this.document.querySelectorAll('.todo-list .edit');
  const input = edits[pos - 1];
  if (input.value !== text)
    throw new Error(`Expected edit value "${text}", got "${input.value}"`);
});

Then('the filter {string} is selected', function (name) {
  const links = this.document.querySelectorAll('.filters a');
  for (const a of links) {
    if (a.textContent === name) {
      if (!a.classList.contains('selected'))
        throw new Error(`Expected filter "${name}" to be selected`);
      return;
    }
  }
  throw new Error(`Filter "${name}" not found`);
});

