(function () {
  'use strict';

  var STORAGE_KEY = 'todos-todomvc';
  var newTodoInput = document.querySelector('.new-todo');
  var todoList = document.querySelector('.todo-list');
  var toggleAll = document.querySelector('#toggle-all');
  var mainSection = document.querySelector('.main');
  var footer = document.querySelector('.footer');
  var counter = document.querySelector('.todo-count');
  var clearCompletedBtn = document.querySelector('.clear-completed');
  var filters = document.querySelectorAll('.filters a');

  var todos = [];

  function generateId() {
    return Date.now().toString(36) + Math.random().toString(36).substr(2);
  }

  function save() {
    localStorage.setItem(STORAGE_KEY, JSON.stringify(todos));
  }

  function load() {
    try {
      todos = JSON.parse(localStorage.getItem(STORAGE_KEY)) || [];
    } catch (e) {
      todos = [];
    }
  }

  function getActiveFilter() {
    var hash = window.location.hash || '#/';
    if (hash === '#/active') return 'active';
    if (hash === '#/completed') return 'completed';
    return 'all';
  }

  function getFilteredTodos() {
    var filter = getActiveFilter();
    if (filter === 'active') return todos.filter(function (t) { return !t.completed; });
    if (filter === 'completed') return todos.filter(function (t) { return t.completed; });
    return todos.slice();
  }

  function updateCounter() {
    var active = todos.filter(function (t) { return !t.completed; }).length;
    var word = active === 1 ? 'item' : 'items';
    counter.innerHTML = '<strong>' + active + '</strong> ' + word + ' left';
  }

  function updateToggleAll() {
    var allCompleted = todos.length > 0 && todos.every(function (t) { return t.completed; });
    toggleAll.checked = allCompleted;
  }

  function updateVisibility() {
    if (todos.length === 0) {
      mainSection.style.display = 'none';
      footer.style.display = 'none';
    } else {
      mainSection.style.display = '';
      footer.style.display = '';
    }
  }

  function updateClearCompleted() {
    var hasCompleted = todos.some(function (t) { return t.completed; });
    clearCompletedBtn.style.display = hasCompleted ? '' : 'none';
  }

  function updateFilters() {
    var filter = getActiveFilter();
    for (var i = 0; i < filters.length; i++) {
      var a = filters[i];
      if (a.textContent === 'All' && filter === 'all') a.classList.add('selected');
      else if (a.textContent === 'Active' && filter === 'active') a.classList.add('selected');
      else if (a.textContent === 'Completed' && filter === 'completed') a.classList.add('selected');
      else a.classList.remove('selected');
    }
  }

  function render() {
    todoList.innerHTML = '';
    var filtered = getFilteredTodos();
    filtered.forEach(function (todo) {
      var li = document.createElement('li');
      li.dataset.id = todo.id;
      if (todo.completed) li.classList.add('completed');

      var view = document.createElement('div');
      view.className = 'view';

      var checkbox = document.createElement('input');
      checkbox.className = 'toggle';
      checkbox.type = 'checkbox';
      checkbox.checked = todo.completed;

      var label = document.createElement('label');
      label.textContent = todo.title;

      var destroyBtn = document.createElement('button');
      destroyBtn.className = 'destroy';

      view.appendChild(checkbox);
      view.appendChild(label);
      view.appendChild(destroyBtn);

      var editInput = document.createElement('input');
      editInput.className = 'edit';
      editInput.value = todo.title;

      li.appendChild(view);
      li.appendChild(editInput);
      todoList.appendChild(li);
    });
    updateCounter();
    updateToggleAll();
    updateVisibility();
    updateClearCompleted();
    updateFilters();
  }

  function addTodo(title) {
    var trimmed = title.trim();
    if (!trimmed) return;
    todos.push({ id: generateId(), title: trimmed, completed: false });
    save();
    render();
  }

  function toggleTodo(id) {
    for (var i = 0; i < todos.length; i++) {
      if (todos[i].id === id) {
        todos[i].completed = !todos[i].completed;
        break;
      }
    }
    save();
    render();
  }

  function destroyTodo(id) {
    todos = todos.filter(function (t) { return t.id !== id; });
    save();
    render();
  }

  function toggleAllTodos() {
    var allCompleted = todos.every(function (t) { return t.completed; });
    todos.forEach(function (t) { t.completed = !allCompleted; });
    save();
    render();
  }

  function clearCompleted() {
    todos = todos.filter(function (t) { return !t.completed; });
    save();
    render();
  }

  function saveEdit(id, newTitle) {
    var trimmed = newTitle.trim();
    if (!trimmed) {
      destroyTodo(id);
      return;
    }
    for (var i = 0; i < todos.length; i++) {
      if (todos[i].id === id) {
        todos[i].title = trimmed;
        break;
      }
    }
    save();
    render();
  }

  // Event delegation on todoList
  todoList.addEventListener('click', function (e) {
    var li = e.target.closest('li');
    if (!li) return;
    var id = li.dataset.id;

    if (e.target.classList.contains('toggle')) {
      toggleTodo(id);
    } else if (e.target.classList.contains('destroy')) {
      destroyTodo(id);
    }
  });

  // Double-click to edit
  todoList.addEventListener('dblclick', function (e) {
    var li = e.target.closest('li');
    if (!li) return;
    if (e.target.tagName !== 'LABEL') return;
    li.classList.add('editing');
    var editInput = li.querySelector('.edit');
    editInput.focus();
  });

  // Edit input events
  todoList.addEventListener('keydown', function (e) {
    if (!e.target.classList.contains('edit')) return;
    var li = e.target.closest('li');
    var id = li.dataset.id;
    if (e.key === 'Enter') {
      e.preventDefault();
      saveEdit(id, e.target.value);
    } else if (e.key === 'Escape') {
      e.target.value = li.querySelector('label').textContent;
      li.classList.remove('editing');
    }
  });

  todoList.addEventListener('blur', function (e) {
    if (!e.target.classList.contains('edit')) return;
    var li = e.target.closest('li');
    if (!li.classList.contains('editing')) return;
    var id = li.dataset.id;
    saveEdit(id, e.target.value);
  }, true);

  // New todo input
  newTodoInput.addEventListener('keydown', function (e) {
    if (e.key === 'Enter') {
      addTodo(newTodoInput.value);
      newTodoInput.value = '';
    }
  });

  // Toggle all
  toggleAll.addEventListener('click', function () {
    toggleAllTodos();
  });

  // Clear completed
  clearCompletedBtn.addEventListener('click', function () {
    clearCompleted();
  });

  // Routing
  function handleRoute() {
    render();
  }

  window.addEventListener('hashchange', handleRoute);

  // Initial load
  load();
  render();
})();

